// Имена компонентов Jinx UI и сигнатуры onChange заданы по типовому соглашению библиотеки — сверьте с версией пакета.
import { useState, type FormEvent } from 'react';
import { Button, Field, Input, Select, Stack, Switch } from '@jinx-ui/react';

export type Language = 'ru' | 'en';

export interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

export interface ProfileSettingsFormProps {
  initialSettings?: Partial<ProfileSettings>;
  onSave: (settings: ProfileSettings) => void;
}

function ProfileSettingsForm({ initialSettings, onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<Language>(initialSettings?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.emailNotifications ?? false,
  );

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name: name.trim(), language, emailNotifications });
  };

  return (
    <form onSubmit={handleSubmit}>
      <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
        <Field label="Имя" htmlFor="profile-name">
          <Input
            id="profile-name"
            value={name}
            onChange={(event) => setName(event.target.value)}
            placeholder="Введите имя"
          />
        </Field>

        <Field label="Язык интерфейса" htmlFor="profile-language">
          <Select
            id="profile-language"
            value={language}
            onChange={(value: Language) => setLanguage(value)}
          >
            <Select.Option value="ru">Русский</Select.Option>
            <Select.Option value="en">Английский</Select.Option>
          </Select>
        </Field>

        <Switch
          checked={emailNotifications}
          onChange={(checked: boolean) => setEmailNotifications(checked)}
          label="Уведомления на почту"
        />

        <Button type="submit" variant="primary">
          Сохранить
        </Button>
      </Stack>
    </form>
  );
}

export default ProfileSettingsForm;

